 if(phase==4&&Time.time-start>2){Check(a.stunned==false,"Stun ends after1.2 seconds");Check(caster.unitState!=UnitStates.AbilityCasting,"Cast returns to idle");Check(Cast(courage),"Courage button cast accepted");phase=5;start=Time.time;return;}
 if(phase==5&&Time.time-start>.5f){Check(Mathf.Abs(caster.attackSpeed-speed/1.3f)<.01f,"Courage grants30percent attack speed");a.SetHP(10000);b.SetHP(10000);b.agent.Warp(center+Vector3.back*1.8f);caster.DealDamage(a,100,physical,true,a.transform.position);Check(a.health==9900&&b.health==9900,"Courage splashes full hit around caster without duplicate primary");float bh=b.health;caster.DealDamage(a,100,physical,false,a.transform.position);Check(b.health==bh,"Indirect damage does not recurse cleave");Capture("haldor-courage.png");phase=6;return;}
