 if(phase==9&&Time.time-start>1.6f){second=Spawn(center+Vector3.right*5,0,true);var c2=second.abilities.OfType<CompositeSkill>().Single(x=>x.name=="Haldor_Courage");courage.Use(caster,0,0);c2.Use(second,0,0);Check(caster.effectors.Any(e=>e.effector==fury)&&second.effectors.Any(e=>e.effector==fury),"Two Haldors have independent courage buffs");second.Die(-1,null,false);Check(caster.effectors.Any(e=>e.effector==fury),"Other caster death does not remove own buff");a.Die(-1,null,false);b.Die(-1,null,false);Check(!strike.AutoCastReady(caster,0,out _),"No target blocks offensive autocast");a=Spawn(center+Vector3.forward*2,foeOwner);Reset(strike);Cast(strike);a.Die(-1,null,false);phase=10;start=Time.time;return;}
