 static bool Cast(CompositeSkill s)=>caster.UseAbilityItem(Array.IndexOf(caster.abilities,s),false,null,Vector3.zero,true);
 static void Reset(CompositeSkill s)=>caster.ChangeAbilityCooldown(-100,Array.IndexOf(caster.abilities,s),false);
 static void Check(bool ok,string text){results.Add((ok?"PASS ":"FAIL ")+text);if(!ok)errors.Add(text);File.WriteAllLines(W+"haldor-runtime-results.txt",results);}
